// Final verification: JSON validity, arithmetic re-check, and file inventory
const fs = require('fs');

// 1. JSON parses
const j = JSON.parse(fs.readFileSync('/work/workspace/deliverable/parecer.json', 'utf8'));
const sum = j.exposicao.remuneracao_base + j.exposicao.decimo_terceiro + j.exposicao.ferias_terco +
            j.exposicao.fgts + j.exposicao.multa_40 + j.exposicao.aviso_previo + j.exposicao.inss_patronal;

// 2. Independent arithmetic re-check
const checks = {
  "salarios 58x18k": 58 * 18000 === j.exposicao.remuneracao_base,
  "13o 58x1500": 58 * 1500 === j.exposicao.decimo_terceiro,
  "ferias 5x24000": 5 * 24000 === j.exposicao.ferias_terco,
  "fgts 8% de 1.251.000": 0.08 * (1044000 + 87000 + 120000) === j.exposicao.fgts,
  "multa 40% do FGTS": 0.4 * j.exposicao.fgts === j.exposicao.multa_40,
  "aviso 51x600": 51 * 600 === j.exposicao.aviso_previo,
  "inss 28% de 1.131.000": 0.28 * (1044000 + 87000) === j.exposicao.inss_patronal,
  "total soma rubricas": sum === j.exposicao.total,
  "com HE": Math.round((sum + 1305 * (18000 / 220) * 1.5) * 100) / 100 === 1898551.09,
  "provisao 70%": Math.round(0.7 * (sum + 1305 * (18000 / 220) * 1.5)) === j.provisao_recomendada.valor,
  "cortes 26+58=84": j.prescricao.meses_prescritos + j.prescricao.meses_exigiveis === 84
};

// 3. Deliverables present
const files = fs.readdirSync('/work/workspace/deliverable').sort();
const req = ['parecer.json', 'parecer.md', 'STATUS.md', 'QUESTIONS.md'].every(f => files.includes(f));

return { jsonValid: true, totalSozinhoNoJSON: j.exposicao.total, checks, semua: Object.values(checks).every(Boolean), deliverables: files, essenciais_presentes: req, status_status: (fs.readFileSync('/work/workspace/deliverable/STATUS.md','utf8').match(/`(COMPLETE(?: WITH OPEN ITEMS)?|BLOCKED)`/) || [])[1] }

